import{_ as t,c as i,o,j as r,Y as s,t as n}from"./chunks/framework.BNTND4LZ.js";const v=JSON.parse('{"title":"git-upload-archive | x-cmd man (git man1) | Send archive back to git-archive","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-upload-archive - Send archive back to git-archive","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-upload-archive | x-cmd man (git man1) | Send archive back to git-archive"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-upload-archive - Send archive back to git-archive"}]]},"headers":[],"params":{"isMan":true,"man":"git-upload-archive","category":"git man1","desc":"Send archive back to git-archive"},"relativePath":"git/man1/git-upload-archive.md","filePath":"git/man1/[man].md"}'),h={name:"git/man1/git-upload-archive.md"},c={class:"visually-hidden"};function l(a,e,p,d,g,m){return o(),i("div",null,[r("h1",c,n(a.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-upload-archive - Send archive back to git-archive</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload-archive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">repositor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Invoked by <em>git archive --remote</em> and sends a generated archive to the other end over the Git protocol.</p><p>This command is usually not invoked directly by the end user. The UI for the protocol is on the <em>git archive</em> side, and the program pair is meant to be used to get an archive from a remote repository.</p><h2 id="security" tabindex="-1">SECURITY <a class="header-anchor" href="#security" aria-label="Permalink to &quot;SECURITY&quot;">​</a></h2><p>In order to protect the privacy of objects that have been removed from history but may not yet have been pruned, <strong>git-upload-archive</strong> avoids serving archives for commits and trees that are not reachable from the repository&#39;s refs. However, because calculating object reachability is computationally expensive, <strong>git-upload-archive</strong> implements a stricter but easier-to-check set of rules:</p><blockquote><p>1.</p><p>Clients may request a commit or tree that is pointed to directly by a ref. E.g., <strong>git archive --remote=origin v1.0</strong>.</p></blockquote><blockquote><p>2.</p><p>Clients may request a sub-tree within a commit or tree using the <strong>ref:path</strong> syntax. E.g., <strong>git archive --remote=origin v1.0:Documentation</strong>.</p></blockquote><blockquote><p>3.</p><p>Clients may <em>not</em> use other sha1 expressions, even if the end result is reachable. E.g., neither a relative commit like <strong>master^</strong> nor a literal sha1 like <strong>abcd1234</strong> is allowed, even if the result is reachable from the refs.</p></blockquote><p>Note that rule 3 disallows many cases that do not have any privacy implications. These rules are subject to change in future versions of git, and the server accessed by <strong>git archive --remote</strong> may or may not follow these exact rules.</p><p>If the config option <strong>uploadArchive.allowUnreachable</strong> is true, these rules are ignored, and clients may use arbitrary sha1 expressions. This is useful if you do not care about the privacy of unreachable objects, or if your object database is already publicly available for access via non-smart-http.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>&lt;repository&gt;</p><blockquote><p>The repository to get a tar archive from.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',19))])}const b=t(h,[["render",l]]);export{v as __pageData,b as default};
